// The Piff editor: one CodeMirror pane with live preview, autosave, and
// reloading when PIFF.md changes on disk.
//
// State kept against the disk:
// - `base` is the text the editor last agreed with the disk on (what a save
//   wrote, or what was read), and `baseExists` whether the file existed.
// - `unsaved` is every edit since `base`, as one change set over it.
// A save sends the whole text with `base` as the expected disk content; the
// backend refuses to write if the disk has moved on. The text that comes
// back (with the children section regenerated by nodir-core) is merged in
// as changes, so typing done while the save was in flight is kept.
import { defaultKeymap, history, historyKeymap, indentWithTab } from "@codemirror/commands";
import { markdown, markdownLanguage } from "@codemirror/lang-markdown";
import { ChangeSet, EditorState, Transaction } from "@codemirror/state";
import { EditorView, keymap, placeholder } from "@codemirror/view";

import { api, type PiffDoc } from "../api";
import { livePreview } from "./livePreview";
import { childrenSection, fromDisk, sectionField, setSection, type SectionState } from "./section";
import { diff, overlaps, spanToDoc, type Span } from "./sync";

/** How long typing must pause before an autosave. */
const AUTOSAVE_MS = 600;

export interface EditorHost {
  followLink(href: string): void;
  showError(message: string): void;
  /** A conflict between unsaved edits and a change on disk, or null once
   * it is resolved. */
  showConflict(conflict: { deleted: boolean } | null): void;
  /** Saving, saved, or unsaved edits. */
  showStatus(status: "saving" | "saved" | "unsaved" | "idle"): void;
}

export class PiffEditor {
  readonly view: EditorView;
  private base: string;
  private baseExists: boolean;
  private baseSection: Span | null;
  private unsaved: ChangeSet;
  private readonly sep: string;
  private timer: number | undefined;
  /** The save in flight: the text sent, and edits made since. */
  private inflight: { sent: string; after: ChangeSet; done: Promise<void> } | null = null;
  /** A disk check was requested while a save was in flight. */
  private recheck = false;
  /** What is on disk while a conflict waits for the user. */
  private conflict: PiffDoc | null = null;
  private destroyed = false;

  constructor(
    readonly path: string,
    doc: PiffDoc,
    parent: HTMLElement,
    private readonly host: EditorHost,
  ) {
    this.sep = doc.lineEnding;
    this.base = doc.text;
    this.baseExists = doc.exists;
    this.baseSection = doc.section;
    const state = EditorState.create({
      doc: doc.text,
      extensions: [
        EditorState.lineSeparator.of(this.sep),
        history(),
        keymap.of([
          { key: "Mod-s", run: () => (void this.save(), true) },
          indentWithTab,
          ...historyKeymap,
          ...defaultKeymap,
        ]),
        markdown({ base: markdownLanguage }),
        EditorView.lineWrapping,
        placeholder("Write about this Piff…"),
        childrenSection(),
        livePreview((href) => host.followLink(href)),
        EditorView.contentAttributes.of({ "aria-label": "Piff content", spellcheck: "true" }),
        EditorView.updateListener.of((u) => {
          for (const tr of u.transactions) {
            if (!tr.docChanged || tr.annotation(fromDisk)) continue;
            this.unsaved = this.unsaved.compose(tr.changes);
            if (this.inflight) this.inflight.after = this.inflight.after.compose(tr.changes);
            this.scheduleSave();
          }
        }),
      ],
    });
    this.unsaved = ChangeSet.empty(state.doc.length);
    this.view = new EditorView({ state, parent });
    this.view.dispatch({ effects: setSection.of(this.sectionState(doc, doc.section)) });
  }

  /** Whether there are edits not yet on disk. */
  get dirty() {
    return !this.unsaved.empty;
  }

  get hasConflict() {
    return this.conflict !== null;
  }

  focus() {
    this.view.focus();
  }

  /** Saves any pending edits now. Resolves once they are on disk (or the
   * save failed, which is reported to the host). */
  async flush() {
    if (this.inflight) await this.inflight.done;
    if (this.dirty && !this.conflict) await this.save();
  }

  destroy() {
    this.destroyed = true;
    window.clearTimeout(this.timer);
    this.view.destroy();
  }

  // ---------- saving ----------

  private scheduleSave() {
    this.host.showStatus("unsaved");
    window.clearTimeout(this.timer);
    if (this.conflict) return;
    this.timer = window.setTimeout(() => void this.save(), AUTOSAVE_MS);
  }

  async save(): Promise<void> {
    window.clearTimeout(this.timer);
    if (this.destroyed || this.conflict || !this.dirty) return;
    if (this.inflight) {
      // Edits made meanwhile are picked up when it finishes.
      return this.inflight.done;
    }
    const sent = this.text();
    const expected = this.baseExists ? this.base : null;
    let finish!: () => void;
    const done = new Promise<void>((resolve) => (finish = resolve));
    this.inflight = { sent, after: ChangeSet.empty(this.view.state.doc.length), done };
    this.host.showStatus("saving");
    try {
      const result = await api.savePiff(this.path, sent, expected);
      const { after } = this.inflight;
      this.inflight = null;
      if (this.destroyed) return;
      if (result.kind === "saved") {
        this.merged(sent, after, result.doc);
      } else {
        // The disk moved on; handle it like any external change. The edits
        // since `base` are still unsaved.
        this.onDisk(result.doc);
      }
    } catch (err) {
      this.inflight = null;
      this.host.showError(`Could not save PIFF.md: ${err}`);
    } finally {
      finish();
    }
    if (this.destroyed) return;
    if (this.recheck) {
      this.recheck = false;
      await this.checkDisk();
    }
    if (this.dirty) this.scheduleSave();
    else if (!this.conflict) this.host.showStatus("saved");
  }

  /** `sent` was saved and the disk now holds `doc`; `after` are edits made
   * since `sent`. */
  private merged(sent: string, after: ChangeSet, doc: PiffDoc) {
    // nodir-core's writer keeps every byte outside the children section, so
    // `sent` and `doc.text` differ only inside it (or by the section it
    // appended on a first save): one prefix/suffix diff is exact.
    const written = diff(sent, null, doc.text, null, this.sep);
    this.applyFromDisk(written, after, doc);
  }

  /**
   * Applies `change` (over the text the disk had, `unsavedSince` edits ago)
   * to the editor, keeping those edits, and makes `doc` the new base.
   */
  private applyFromDisk(change: ChangeSet, unsavedSince: ChangeSet, doc: PiffDoc) {
    const forEditor = change.map(unsavedSince);
    this.unsaved = unsavedSince.map(change, true);
    this.base = doc.text;
    this.baseExists = doc.exists;
    this.baseSection = doc.section;
    const section = doc.section && spanToDoc(doc.text, doc.section, this.sep);
    const mapped = section && {
      from: this.unsaved.mapPos(section.from, 1),
      to: this.unsaved.mapPos(section.to, -1),
    };
    this.view.dispatch({
      changes: forEditor,
      effects: setSection.of({ range: mapped, html: doc.childrenHtml }),
      annotations: [fromDisk.of(true), Transaction.addToHistory.of(false)],
      filter: false,
    });
  }

  // ---------- changes on disk ----------

  /** Called when the watcher reports that PIFF.md changed. */
  async checkDisk() {
    if (this.destroyed) return;
    if (this.inflight) {
      this.recheck = true;
      return;
    }
    let doc: PiffDoc;
    try {
      doc = await api.readPiff(this.path);
    } catch (err) {
      this.host.showError(String(err));
      return;
    }
    if (this.destroyed || this.inflight) {
      this.recheck = true;
      return;
    }
    this.onDisk(doc);
  }

  /** The disk holds `doc`. Merge it in, or ask the user if it clashes with
   * unsaved edits. */
  private onDisk(doc: PiffDoc) {
    if (doc.exists === this.baseExists && doc.text === this.base) {
      // Our own write, or a change that was undone. Nothing to merge.
      if (this.conflict) this.resolved();
      this.refreshSectionHtml(doc);
      return;
    }
    const change = diff(this.base, this.baseSection, doc.text, doc.section, this.sep);
    if (!this.dirty || !overlaps(change, this.unsaved)) {
      this.applyFromDisk(change, this.unsaved, doc);
      if (this.conflict) this.resolved();
      if (this.dirty) this.scheduleSave();
      return;
    }
    window.clearTimeout(this.timer);
    this.conflict = doc;
    this.host.showConflict({ deleted: !doc.exists });
  }

  /** Conflict: keep the editor's text, overwriting the file on disk. */
  async keepMine() {
    const doc = this.conflict;
    if (!doc) return;
    // Rebase onto the disk's text: everything that differs is unsaved.
    this.base = doc.text;
    this.baseExists = doc.exists;
    this.baseSection = doc.section;
    this.unsaved = diff(doc.text, null, this.text(), null, this.sep);
    this.resolved();
    if (this.dirty) await this.save();
    else this.host.showStatus("saved");
  }

  /** Conflict: drop unsaved edits and load the file from disk. */
  useDisk() {
    const doc = this.conflict;
    if (!doc) return;
    const current = this.text();
    const change = diff(current, null, doc.text, doc.section, this.sep);
    this.applyFromDisk(change, ChangeSet.empty(change.length), doc);
    this.resolved();
    this.host.showStatus("idle");
  }

  private resolved() {
    this.conflict = null;
    this.host.showConflict(null);
  }

  private refreshSectionHtml(doc: PiffDoc) {
    const current = this.view.state.field(sectionField);
    if (current.html !== doc.childrenHtml) {
      this.view.dispatch({ effects: setSection.of({ range: current.range, html: doc.childrenHtml }) });
    }
  }

  // ---------- helpers ----------

  private text() {
    return this.view.state.sliceDoc();
  }

  private sectionState(doc: PiffDoc, span: Span | null): SectionState {
    return { range: span && spanToDoc(doc.text, span, this.sep), html: doc.childrenHtml };
  }
}
